**FREE
greeting = '';
found = *off;
chain requestedId CustomerRec;
if %found(Customers);
  found = *on;
  greeting = 'Hello ' + %trim(name);
endif;

**FREE
total = 0;
setll requestedId Orders;
reade requestedId Orders;
dow not %eof(Orders);
  total = total + amount;
  reade requestedId Orders;
enddo;

**FREE
result = 'INVALID';
if newQty >= 0;
  result = 'MISSING';
  chain requestedId ProductRec;
  if %found(Products);
    quantity = newQty;
    update ProductRec;
    result = 'UPDATED';
  endif;
endif;

**FREE
read ImportRec;
dow not %eof(Import);
  if status = 'P';
    exsr ProcessOne;
  endif;
  read ImportRec;
enddo;

**FREE
orderId = requestedId;
customerId = requestedCustomer;
amount = requestedAmount;
status = 'NEW';
fileStatus = 0;
write(e) OrderRec;
if %error;
  fileStatus = %status(Orders);
  if fileStatus = 1021;
    result = 'DUPLICATE';
  else;
    result = 'IO_ERROR';
  endif;
else;
  result = 'CREATED';
endif;

**FREE
fileStatus = 0;
result = 'MISSING';
monitor;
  chain requestedId OrderRec;
  if %found(Orders);
    quantity = newQty;
    update OrderRec;
    result = 'UPDATED';
  endif;
on-error 1218;
  fileStatus = %status(Orders);
  result = 'LOCKED';
on-error;
  fileStatus = %status(Orders);
  result = 'IO_ERROR';
endmon;

**FREE
dcl-s rawLine varchar(256);
dcl-s leftText varchar(256);
dcl-s rightText varchar(256);
dcl-s cut int(10);
dcl-s ok ind;
dcl-ds importRow qualified;
  orderId packed(9:0);
  customerId packed(9:0);
end-ds;
clear importRow;
ok = *off;
cut = %scan(',': rawLine);
if cut > 1 and cut < %len(rawLine);
  if %scan(',': rawLine: cut + 1) = 0;
    leftText = %trim(%subst(rawLine: 1: cut - 1));
    rightText = %trim(%subst(rawLine: cut + 1));
    if %len(leftText) > 0 and %len(leftText) <= 9;
      if %len(rightText) > 0 and %len(rightText) <= 9;
        if %check('0123456789': leftText) = 0;
          if %check('0123456789': rightText) = 0;
            importRow.orderId = %dec(leftText: 9: 0);
            importRow.customerId = %dec(rightText: 9: 0);
            ok = importRow.orderId > 0 and importRow.customerId > 0;
          endif;
        endif;
      endif;
    endif;
  endif;
endif;
if not ok;
  clear importRow;
endif;

**FREE
errorText = '';
name = %trim(inputName);
if name = '';
  errorText = 'name is required';
endif;
if errorText = '';
  monitor;
    postingDate = %date(inputDate: *iso);
  on-error;
    errorText = 'date must be valid ISO';
  endmon;
endif;
if errorText = '';
  monitor;
    amount = %dec(inputAmount: 11: 2);
  on-error;
    errorText = 'amount is invalid';
  endmon;
  if errorText = '' and amount < 0;
    errorText = 'amount cannot be negative';
  endif;
endif;

**FREE
dcl-pr validateOrder ind;
  orderId packed(9:0) const;
  errorText char(80);
end-pr;

dcl-proc validateOrder;
  dcl-pi *n ind;
    orderId packed(9:0) const;
    errorText char(80);
  end-pi;
errorText = '';
if orderId <= 0;
  errorText = 'orderId must be positive';
  return *off;
endif;
return *on;
end-proc;

**FREE
result = postOrder(orderId);
serviceFailed = result <> 0;

**FREE
exsr ClearSubfile;
sflRrn = 0;
if firstPage;
  setll *loval Orders;
else;
  setgt lastId Orders;
endif;
read Orders;
dow not %eof(Orders) and sflRrn < pageSize;
  sflRrn = sflRrn + 1;
  exsr CopyToScreen;
  write SflRecord;
  lastId = orderId;
  read Orders;
enddo;
hasMore = not %eof(Orders);

**FREE
readc SflRecord;
dow not %eof(Display);
  if editedQty >= 0;
    exsr UpdateOne;
    if not updateOk;
      exsr MarkError;
    endif;
  else;
    exsr MarkError;
  endif;
  readc SflRecord;
enddo;

**FREE
exec sql insert into appdata.orders
    (order_id, customer_id, amount)
  values (:orderId, :customerId, :amount);
savedState = SQLSTT;
select;
when savedState = '00000';
  result = 'INSERTED';
when savedState = '23505';
  result = 'DUPLICATE';
when savedState = '23503';
  result = 'MISSING_PARENT';
other;
  result = 'SQL_CONDITION';
endsl;

**FREE
exec sql declare C1 cursor for
  select order_id, amount from appdata.orders
  where order_id > :lastId order by order_id
  for read only;
rowCount = 0;
hasMore = *off;
cursorOpen = *off;
savedState = '00000';
exec sql open C1;
savedState = SQLSTT;
if savedState = '00000';
  cursorOpen = *on;
  dow rowCount < pageSize;
    exec sql fetch C1 into :orderId, :amount;
    savedState = SQLSTT;
    if savedState <> '00000';
      leave;
    endif;
    rowCount = rowCount + 1;
    exsr CopyRow;
    lastId = orderId;
  enddo;
  hasMore = rowCount = pageSize;
endif;
if cursorOpen;
  exec sql close C1;
  closeState = SQLSTT;
  cursorOpen = *off;
  if savedState = '00000' or savedState = '02000';
    if closeState <> '00000';
      savedState = closeState;
    endif;
  endif;
endif;

**FREE
firstState = '00000';
affected = 0;
exec sql update appdata.orders set status = 'POSTED'
  where order_id = :orderId and status = 'OPEN';
firstState = SQLSTT;
if firstState = '00000';
  exec sql get diagnostics :affected = row_count;
  firstState = SQLSTT;
endif;
if firstState = '00000' and affected = 1;
  exec sql insert into appdata.order_audit
      (order_id, posted_at)
    values (:orderId, current_timestamp);
  firstState = SQLSTT;
endif;
if firstState = '00000' and affected = 1;
  exec sql commit;
  endState = SQLSTT;
  if endState = '00000';
    result = 'COMMITTED';
  else;
    result = 'COMMIT_ERROR';
  endif;
else;
  exec sql rollback;
  endState = SQLSTT;
  if endState = '00000';
    result = 'NOT_POSTED';
  else;
    result = 'RECOVERY_ERR';
  endif;
endif;

**FREE
queueName = 'ORDERQ';
libraryName = 'APPDATA';
waitSeconds = 5;
dataLength = 0;
clear queueData;
callp ReceiveQueue(queueName: libraryName: dataLength: queueData: waitSeconds);
if dataLength = 0;
  result = 'NO_WORK';
else;
  exsr ProcessQueue;
